INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_42_m_42_5_26',
  'Which AWS service provides a graphical interface to view, understand, and analyze your AWS costs and usage over time, allowing for forecasting future spending?',
  'mcq',
  '["AWS Cost Explorer, which offers detailed cost visualization and analysis","AWS Budgets, for setting custom cost and usage alerts","AWS Trusted Advisor, for providing cost optimization recommendations","AWS Billing Dashboard, which shows a high-level overview of current charges"]'::json,
  '{0}',
  'Option A (correct) is AWS Cost Explorer, which provides a graphical interface to visualize, understand, and manage your AWS costs and usage over time, including forecasting capabilities. Option B, AWS Budgets, is for setting alerts. Option C, AWS Trusted Advisor, provides recommendations. Option D, AWS Billing Dashboard, offers a summary but not the detailed analysis and forecasting of Cost Explorer.',
  NOW(),
  'quiz_domain42_9',
  NOW(),
  106,
  NULL,
  NULL,
  'm_42_5',
  'easy'
