INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_36',
  'A development team wants to ensure their AWS architecture adheres to best practices and continuously improves. Which AWS service provides a framework and tools to review their workloads against operational excellence, security, reliability, performance efficiency, and cost optimization?',
  'mcq',
  '["AWS Well-Architected Tool","AWS Systems Manager Automation","Amazon CloudWatch","AWS Compute Optimizer"]'::json,
  '{0}',
  'Option A (correct) is the AWS Well-Architected Tool, which provides a framework and a set of tools to review workloads against best practices across six pillars, including operational excellence. It helps identify high-risk issues and provides guidance for improvement. Option B (incorrect) AWS Systems Manager Automation is used for automating operational tasks, not for conducting architectural reviews. Option C (incorrect) Amazon CloudWatch is a monitoring service for metrics, logs, and events, which is part of an observability strategy but not a framework for architectural reviews. Option D (incorrect) AWS Compute Optimizer focuses on right-sizing compute resources for performance and cost, not a comprehensive architectural review framework.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  12,
  NULL,
