INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_3_38',
  'A company wants to improve the price/performance ratio of its compute-intensive workloads running on Amazon EC2. Which AWS technology offers a significant improvement in this area by utilizing custom-designed processors?',
