INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_43_m_43_1_24',
  'A development team wants to deploy a new version of their application with minimal downtime and the ability to quickly roll back if issues arise. They also want to test the new version with a small subset of users before a full rollout. Which deployment strategy is best suited for this requirement?',
  'mcq',
  '["In-place deployment","Blue/green deployment","Rolling update","All-at-once deployment"]'::json,
  '{1}',
  'Option B (Blue/green deployment) is ideal for minimizing downtime and enabling quick rollbacks. It involves deploying the new version (green environment) alongside the current version (blue environment) and then shifting traffic. This allows for testing with a subset of users before a full cutover. Option A (In-place deployment) updates instances directly, leading to potential downtime and complex rollbacks. Option C (Rolling update) updates instances in batches, reducing downtime but still involving direct updates and potentially slower rollbacks. Option D (All-at-once deployment) updates all instances simultaneously, causing significant downtime and high risk.',
  NOW(),
  'quiz_domain43_9',
  NOW(),
  4,
  NULL,
  NULL,
  'm_43_1',
  'easy'
);

