INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_43_m_43_5_28',
  'A solutions architect needs to improve the performance of a read-heavy web application that frequently queries a backend Amazon RDS database. The application''s data changes infrequently. Which AWS service should be implemented to reduce the load on the database and speed up data retrieval?',
