INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_43_m_43_3_21',
  'Which AWS service provides a managed service for creating and controlling encryption keys used to encrypt your data across various AWS services and applications?',
  'mcq',
  '["AWS IAM","AWS KMS","AWS CloudHSM","AWS Secrets Manager"]'::json,
  '{1}',
  'Option B (AWS KMS) is a managed service that makes it easy for you to create and control the encryption keys used to encrypt your data. It integrates with many AWS services to encrypt data at rest and in transit. Option A (AWS IAM) manages access to AWS resources. Option C (AWS CloudHSM) provides dedicated hardware security modules, a more specialized service for FIPS 140-2 Level 3 compliance. Option D (AWS Secrets Manager) stores and manages secrets like database credentials.',
  NOW(),
  'quiz_domain43_9',
  NOW(),
  105,
  NULL,
  NULL,
  'm_43_3',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_43_m_43_3_22',
  'Which AWS service is used to securely store, manage, and rotate sensitive information such as database credentials, API keys, and other secrets throughout their lifecycle?',
