INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_51',
  'A solutions architect is tasked with improving the operational excellence of an existing solution. Which AWS services and practices are directly involved in conducting Well-Architected Framework reviews and implementing subsequent improvement plans? (Select TWO.)',
  'multiple',
  '["AWS Well-Architected Tool","AWS Systems Manager Automation","Amazon GuardDuty","AWS IAM Access Analyzer","Amazon RDS Performance Insights"]'::json,
  '{0,1}',
  'Option A (correct) is the dedicated service for conducting Well-Architected Framework reviews and identifying areas for improvement across the six pillars. Option B (correct) can be used to automate operational runbooks and implement the automated aspects of improvement plans identified during a Well-Architected Review, directly contributing to operational excellence. Option C (Amazon GuardDuty) is a threat detection service. Option D (AWS IAM Access Analyzer) helps identify unintended external access to resources. Option E (Amazon RDS Performance Insights) is for database performance analysis.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  1,
  NULL,
  NULL,
  'm_44_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
