);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_82',
  'A company wants to improve its operational excellence by ensuring that its AWS environment continuously adheres to security and compliance standards. Which AWS services can assist in automating compliance checks and remediating non-compliant resources? (Select TWO.)',
  'multiple',
  '["AWS Config","AWS Systems Manager Automation","Amazon CloudWatch","AWS Security Hub","Amazon GuardDuty"]'::json,
  '{0,1}',
  'AWS Config (Option A) allows you to assess, audit, and evaluate the configurations of your AWS resources, providing continuous monitoring and compliance checking against desired configurations. AWS Systems Manager Automation (Option B) can be used to create runbooks that automatically remediate non-compliant resources identified by AWS Config. Amazon CloudWatch (Option C) provides monitoring and alarms but not direct compliance enforcement or remediation. AWS Security Hub (Option D) aggregates security findings but doesn''t automate remediation directly. Amazon GuardDuty (Option E) is a threat detection service.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  32,
  NULL,
  NULL,
  'm_44_1',
  'medium'
);

