INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_84',
  'A company wants to ensure that its application deployments are highly available and minimize downtime during updates. Which deployment strategies, when combined with Infrastructure as Code, contribute significantly to operational excellence? (Select TWO.)',
  'multiple',
  '["Blue/Green Deployments","Rolling Deployments","In-place Upgrades","Manual Deployments","Big-bang Deployments"]'::json,
  '{0,1}',
  'Blue/Green Deployments (Option A) involve running two identical production environments (Blue and Green) and shifting traffic between them, minimizing downtime and risk during updates. Rolling Deployments (Option B) update a subset of instances at a time, gradually replacing the old version with the new one, which also minimizes downtime. In-place Upgrades (Option C) typically involve downtime and higher risk. Manual Deployments (Option D) are prone to human error and lack repeatability. Big-bang Deployments (Option E) release all changes at once, carrying high risk and potential for significant downtime.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  34,
  NULL,
  NULL,
  'm_44_1',
  'medium'
);

