  NULL,
  'm_45_1',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_1_46',
  'Which AWS service helps assess on-premises server workloads by collecting configuration, usage, and performance data for migration planning?',
  'mcq',
  '["AWS Migration Hub","AWS Application Discovery Service","AWS Systems Manager","AWS Config"]'::json,
  '{1}',
  'Option B (AWS Application Discovery Service) is the correct service. It helps identify applications, their dependencies, and collect performance data from on-premises servers to assist in migration planning and TCO analysis. Option A (AWS Migration Hub) provides a centralized view of migration progress but relies on discovery tools like Application Discovery Service. Option C (AWS Systems Manager) is for operational management of AWS and on-premises resources, not specifically for discovery for migration. Option D (AWS Config) assesses, audits, and evaluates the configurations of your AWS resources.',
  NOW(),
  'quiz_domain45_9',
