INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_2_29',
  'Which AWS service is specifically designed to simplify and automate the rehosting (lift-and-shift) of physical servers, virtual machines, and cloud instances to AWS?',
  'mcq',
