INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_2_30',
  'A company needs to migrate a 50 TB on-premises database to Amazon Aurora with minimal downtime. The database schema is compatible, but the data volume is very large. Which AWS service is best suited for this task?',
  'mcq',
  '["AWS Application Migration Service (MGN)","AWS Database Migration Service (DMS)","AWS DataSync","AWS Schema Conversion Tool (SCT)"]'::json,
  '{1}',
  'Option B (AWS Database Migration Service (DMS)) is designed for migrating databases to AWS quickly and securely, supporting continuous data replication for minimal downtime. Option A (AWS Application Migration Service (MGN)) is for server rehosting. Option C (AWS DataSync) is for file/object data transfer. Option D (AWS Schema Conversion Tool (SCT)) is for converting database schemas, not the actual data migration.',
  NOW(),
  'quiz_domain45_9',
  NOW(),
  26,
  NULL,
  NULL,
  'm_45_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_2_31',
  'What is the primary function of the AWS Schema Conversion Tool (SCT)?',
  'mcq',
  '["Migrate data from on-premises databases to AWS.","Automate the rehosting of entire servers to AWS.","Convert existing database schemas and code objects from one database engine to another.","Transfer large amounts of file data to AWS storage services."]'::json,
  '{2}',
  'Option C (AWS Schema Conversion Tool (SCT)) is used to convert the database schema and application code from a source database engine to a target database engine, such as migrating from Oracle to Amazon Aurora PostgreSQL. Option A describes AWS Database Migration Service (DMS). Option B describes AWS Application Migration Service (MGN). Option D describes AWS DataSync.',
  NOW(),
  'quiz_domain45_9',
