  NULL,
  'm_45_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_2_32',
  'A research institution needs to transfer 800 TB of scientific data from an on-premises data center located in a remote area with very limited internet connectivity to Amazon S3. Which AWS service would be the most efficient and reliable for this offline data migration?',
  'mcq',
  '["AWS DataSync","AWS Database Migration Service (DMS)","AWS Application Migration Service (MGN)","AWS Snowball Edge"]'::json,
  '{3}',
  'Option D (AWS Snowball Edge) is part of the AWS Snow Family, designed for offline data transfer of petabyte-scale data when network bandwidth is limited or non-existent. Option A (AWS DataSync) is for online data transfer. Option B (AWS Database Migration Service (DMS)) is for database migrations. Option C (AWS Application Migration Service (MGN)) is for server rehosting.',
  NOW(),
  'quiz_domain45_9',
