  NULL,
  'm_45_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_2_33',
  'Which AWS service enables you to transfer large amounts of data online between on-premises storage and AWS storage services like Amazon S3, Amazon EFS, or Amazon FSx?',
  'mcq',
  '["AWS DataSync","AWS Snowball","AWS Database Migration Service (DMS)","AWS Application Migration Service (MGN)"]'::json,
  '{0}',
