INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_4_29',
  'Which AWS service enables you to run code without provisioning or managing servers, automatically scaling and managing the underlying infrastructure?',
  'mcq',
  '["Amazon EC2","Amazon ECS","AWS Lambda","Amazon EKS"]'::json,
  '{2}',
  'Option C (AWS Lambda) is the correct service. AWS Lambda is a serverless compute service that lets you run code without provisioning or managing servers. It automatically scales and manages the underlying infrastructure. Option A (Amazon EC2) requires provisioning and managing virtual servers. Option B (Amazon ECS) and Option D (Amazon EKS) are container orchestration services that typically run on EC2 instances, requiring some server management unless using Fargate.',
  NOW(),
  'quiz_domain45_9',
  NOW(),
  74,
  NULL,
  NULL,
  'm_45_4',
  'medium'
