INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_111',
  'A company wants to improve its operational excellence by reviewing and improving its architecture using the AWS Well-Architected Framework. Order the steps to conduct a Well-Architected Review.',
  'ordering',
  '["Document the identified risks and create an action plan for remediation.","Select the workload to be reviewed in the AWS Well-Architected Tool.","Answer questions across the six pillars of the Well-Architected Framework.","Engage stakeholders and subject matter experts for input during the review."]'::json,
  '{1,3,2,0}',
  'To conduct a Well-Architected Review, first select the workload to be reviewed (Option B) within the AWS Well-Architected Tool to define the scope. Next, engage stakeholders and subject matter experts (Option D) to gather diverse perspectives and ensure comprehensive input. Then, answer questions across the six pillars (Option C) of the Well-Architected Framework, assessing the architecture against best practices. Finally, document the identified risks and create an action plan (Option A) for remediation, prioritizing high-severity issues to drive continuous improvement.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  27,
  NULL,
  NULL,
  'm_44_1',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_112',
  'A company wants to improve its operational excellence by automating routine operational runbooks. Order the steps to create and deploy an AWS Systems Manager Automation document for a common task.',
  'ordering',
  '["Test the Automation document on a staging environment.","Define the Automation document''s steps and parameters in YAML or JSON.","Upload the Automation document to Systems Manager Document Store.","Execute the Automation document on target resources."]'::json,
  '{1,2,0,3}',
  'To automate operational runbooks, first define the Automation document''s steps and parameters (Option B) in a structured format like YAML or JSON, outlining the desired actions. Next, upload the Automation document (Option C) to Systems Manager Document Store to make it available. Then, test the Automation document (Option A) on a staging environment to ensure it functions as expected without impacting production. Finally, execute the Automation document (Option D) on target resources in the production environment to perform the automated task.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  28,
  NULL,
  NULL,
  'm_44_1',
  'medium'
