INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_1_113',
  'A company wants to improve its observability by correlating metrics, logs, and traces to gain deeper insights into application behavior. Order the steps to achieve this correlation using AWS services.',
  'ordering',
  '["Create Amazon CloudWatch dashboards to visualize correlated data.","Instrument application code with AWS X-Ray SDK for tracing.","Configure Amazon CloudWatch Logs to collect application logs.","Enable Amazon CloudWatch metrics for relevant services and resources."]'::json,
  '{3,2,1,0}',
  'To correlate metrics, logs, and traces, first enable Amazon CloudWatch metrics (Option D) for relevant services and resources to gather performance data. Next, configure Amazon CloudWatch Logs (Option C) to collect detailed application logs. Concurrently, instrument application code with AWS X-Ray SDK (Option B) to generate distributed traces. Finally, create Amazon CloudWatch dashboards (Option A) to visualize and correlate these metrics, logs, and traces, providing a unified view of application behavior and aiding in troubleshooting.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  29,
  NULL,
  NULL,
  'm_44_1',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
