INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_3_75',
  'A developer wants to use AWS X-Ray to trace requests and identify performance bottlenecks in an application running on Amazon EC2. Order the initial steps to set up X-Ray.',
  'ordering',
  '["Deploy the X-Ray daemon on the EC2 instances.","Integrate the X-Ray SDK into the application code.","View service maps and trace details in the X-Ray console.","Configure an IAM role with X-Ray permissions for EC2."]'::json,
  '{3,1,0,2}',
  'The initial setup for AWS X-Ray involves granting permissions, instrumenting the application, and running the daemon. Option D (Configure an IAM role with X-Ray permissions for EC2) is the prerequisite for EC2 instances to send trace data to X-Ray. Option B (Integrate the X-Ray SDK into the application code) instruments the application to generate trace data. Option A (Deploy the X-Ray daemon on the EC2 instances) collects the raw segment data from the application and relays it to the X-Ray service. Option C (View service maps and trace details in the X-Ray console) is the final step to analyze the collected data.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  34,
  NULL,
  NULL,
  'm_44_3',
  'easy'
);

