INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_3_82',
  'After integrating AWS X-Ray, a developer needs to use it to identify performance bottlenecks in their application. Order the steps to analyze traces for bottlenecks.',
