INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_3_83',
  'Order the steps to use AWS X-Ray to profile an application and identify performance bottlenecks.',
  'ordering',
  '["Analyze the service map and trace timelines in the X-Ray console.","Instrument the application code with the AWS X-Ray SDK.","Deploy the instrumented application and generate traffic.","Configure sampling rules to control data ingestion."]'::json,
  '{1,3,2,0}',
  'To profile an application with AWS X-Ray, the initial step is to instrument the application code with the AWS X-Ray SDK (Option B) to enable tracing. Before deployment, configure sampling rules (Option D) to control which requests are traced and at what rate. Then, deploy the instrumented application and generate traffic (Option C) to produce trace data. Finally, analyze the service map and trace timelines in the X-Ray console (Option A) to visualize request flows and identify performance bottlenecks. Option A is the analysis step after data collection. Option C must follow instrumentation. Option D is a configuration step before deployment.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  42,
  NULL,
  NULL,
  'm_44_3',
  'medium'
);

