);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_3_93',
  'A company needs to identify and resolve performance bottlenecks in their Amazon RDS for MySQL database. Order the steps to effectively use Amazon RDS Performance Insights for this task.',
