INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_3_95',
  'A team wants to improve the performance of their web application by identifying and resolving bottlenecks using AWS X-Ray. Order the steps to implement and analyze traces with AWS X-Ray.',
  'ordering',
  '["Analyze the service map and trace details in the AWS X-Ray console to pinpoint bottlenecks.","Instrument application code with the AWS X-Ray SDK to send trace data.","Configure the X-Ray daemon on EC2 instances or integrate with AWS Lambda.","Deploy the instrumented application and generate traffic to collect traces."]'::json,
  '{1,2,3,0}',
  'To effectively use AWS X-Ray, first instrument the application code (Option B) with the AWS X-Ray SDK to generate and send trace data. Next, configure the X-Ray daemon (Option C) on EC2 instances or integrate with AWS Lambda to collect and relay the trace data to the X-Ray service. Then, deploy the instrumented application (Option D) and generate traffic to ensure traces are being collected. Finally, analyze the service map and trace details (Option A) in the AWS X-Ray console to pinpoint performance bottlenecks and latency issues within the application.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  54,
  NULL,
  NULL,
  'm_44_3',
  'medium'
);

