INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_4_56',
  'To enhance the reliability of an Amazon RDS database, a solutions architect plans to enable Multi-AZ deployment. Order the steps to configure Multi-AZ for an existing RDS instance.',
  'ordering',
  '["Monitor the RDS instance for failover readiness.","Modify the RDS instance to enable Multi-AZ.","Verify the Multi-AZ status in the RDS console.","Test failover capabilities (e.g., by rebooting the primary instance)."]'::json,
  '{1,2,0,3}',
  'Enabling Multi-AZ for an Amazon RDS instance involves modification, verification, monitoring, and testing. Option B (Modify the RDS instance to enable Multi-AZ) is the direct action to initiate the Multi-AZ configuration. Option C (Verify the Multi-AZ status in the RDS console) confirms that the change is being applied and the standby replica is being created. Option A (Monitor the RDS instance for failover readiness) ensures that the system is stable and ready for potential failovers. Option D (Test failover capabilities (e.g., by rebooting the primary instance)) is a critical step to validate the reliability improvement.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
