INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_5_60',
  'A company wants to optimize its AWS costs by identifying and terminating unused resources. Order the steps to conduct a review for unused resources.',
  'ordering',
  '["Identify unused resources such as unattached EBS volumes, idle EC2 instances, or old snapshots.","Review AWS Cost Explorer and AWS Trusted Advisor for cost optimization recommendations.","Terminate or archive identified unused resources.","Monitor the impact on billing and operational efficiency."]'::json,
  '{1,0,2,3}',
  'To optimize costs by terminating unused resources, first review AWS Cost Explorer and AWS Trusted Advisor (Option B) for cost optimization recommendations, which often highlight idle resources. Next, identify specific unused resources (Option A) such as unattached EBS volumes, idle EC2 instances, or old snapshots that are incurring unnecessary costs. Then, terminate or archive (Option C) these identified unused resources, ensuring proper backups or retention policies are followed if necessary. Finally, monitor the impact on billing and operational efficiency (Option D) to confirm the cost savings and ensure no critical services were inadvertently affected.',
  NOW(),
  'quiz_domain44_9',
  NOW(),
  114,
  NULL,
  NULL,
  'm_44_5',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_44_m_44_5_61',
  'A solutions architect needs to improve the cost-effectiveness of an application by migrating from on-demand EC2 instances to Reserved Instances or Savings Plans. Order the steps to evaluate and implement these cost-saving mechanisms.',
  'ordering',
  '["Purchase the recommended Reserved Instances or Savings Plans.","Analyze historical EC2 usage patterns using AWS Cost Explorer.","Evaluate the recommendations for Reserved Instances and Savings Plans.","Monitor the utilization and coverage of the purchased commitments."]'::json,
  '{1,2,0,3}',
