INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_1_85',
  'A company is evaluating its application portfolio for cloud migration. Order the initial steps to apply the 7 Rs of migration framework.',
  'ordering',
  '["Categorize applications based on business value and technical complexity","Identify applications suitable for rehosting (lift and shift)","Inventory all on-premises applications and infrastructure","Determine applications to retain or retire"]'::json,
  '{2,0,3,1}',
  'The initial step in applying the 7 Rs framework is to inventory all on-premises applications and infrastructure (Option C) to understand the current state. Next, categorize applications based on their business value and technical complexity (Option A) to inform strategic decisions. Based on this, determine which applications to retain or retire (Option D) as they may not be suitable for migration. Finally, identify applications suitable for rehosting (lift and shift) (Option B), which is often the quickest migration path for compatible workloads.',
  NOW(),
  'quiz_domain45_9',
  NOW(),
  10,
  NULL,
  NULL,
  'm_45_1',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
