INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_45_m_45_2_95',
  'A solutions architect is implementing the Strangler Fig pattern to modernize a monolithic application. Order the conceptual steps for applying this pattern.',
  'ordering',
  '["Identify a specific module or functionality to extract from the monolith.","Build the new, modernized service in AWS, independent of the monolith.","Gradually route increasing amounts of traffic from the monolith to the new service.","Decommission the corresponding functionality within the original monolithic application."]'::json,
  '{0,1,2,3}',
  'The Strangler Fig pattern starts by identifying a specific module (Option A) within the monolith that can be independently extracted. Next, the new, modernized service is built (Option B) in AWS. Traffic is then gradually routed (Option C) from the old module to the new service. Once the new service is fully operational and handling all traffic, the old functionality in the monolith is decommissioned (Option D).',
  NOW(),
  'quiz_domain45_9',
  NOW(),
  46,
  NULL,
  NULL,
  'm_45_2',
  'medium'
);

